import{_ as o,o as t,c as s,a2 as r}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Kubernetes","description":"Kubernetes reference documentation","frontmatter":{"title":"Kubernetes","description":"Kubernetes reference documentation"},"headers":[],"relativePath":"knowledge/kubernetes.md","filePath":"knowledge/kubernetes.md","lastUpdated":1784485118000}'),a={name:"knowledge/kubernetes.md"};function n(i,e,l,c,d,u){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="kubernetes" tabindex="-1">Kubernetes <a class="header-anchor" href="#kubernetes" aria-label="Permalink to &quot;Kubernetes&quot;">​</a></h1><h1 id="kubernetes-knowledge-document" tabindex="-1">Kubernetes Knowledge Document <a class="header-anchor" href="#kubernetes-knowledge-document" aria-label="Permalink to &quot;Kubernetes Knowledge Document&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Kubernetes (K8s) is an open-source container orchestration platform that automates deployment, scaling, and management of containerized applications. It provides self-healing, load balancing, service discovery, and rolling updates. Understanding Kubernetes is essential for operating production workloads at scale, managing microservices architectures, and working with cloud-native applications.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="pods" tabindex="-1">Pods <a class="header-anchor" href="#pods" aria-label="Permalink to &quot;Pods&quot;">​</a></h3><p>A Pod is the smallest deployable unit — one or more co-located containers that share network and storage. Most Pods run a single container. Pods are ephemeral; they are created, scheduled, and destroyed by the controller.</p><h3 id="deployments" tabindex="-1">Deployments <a class="header-anchor" href="#deployments" aria-label="Permalink to &quot;Deployments&quot;">​</a></h3><p>A Deployment manages ReplicaSets and provides declarative updates. It handles rolling updates, rollbacks, and scaling. The desired state is declared in a manifest; the controller continuously reconciles actual state with desired state.</p><h3 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h3><p>A Service provides stable network identity for a set of Pods. Types:</p><ul><li><strong>ClusterIP</strong> (default) — Internal access within the cluster</li><li><strong>NodePort</strong> — Exposes on a static port on each node</li><li><strong>LoadBalancer</strong> — Provisions cloud load balancer</li><li><strong>ExternalName</strong> — Maps to a DNS name outside the cluster</li></ul><h3 id="ingress" tabindex="-1">Ingress <a class="header-anchor" href="#ingress" aria-label="Permalink to &quot;Ingress&quot;">​</a></h3><p>Ingress manages external HTTP/HTTPS routing to Services. It provides host-based and path-based routing, TLS termination, and name-based virtual hosting. Ingress controllers (NGINX, Traefik, Cloudflare) implement the Ingress resource.</p><h3 id="configmaps-and-secrets" tabindex="-1">ConfigMaps and Secrets <a class="header-anchor" href="#configmaps-and-secrets" aria-label="Permalink to &quot;ConfigMaps and Secrets&quot;">​</a></h3><p>ConfigMaps store non-sensitive configuration as key-value pairs. Secrets store sensitive data (base64-encoded, not encrypted by default). Both can be mounted as files or injected as environment variables.</p><h3 id="horizontal-pod-autoscaler-hpa" tabindex="-1">Horizontal Pod Autoscaler (HPA) <a class="header-anchor" href="#horizontal-pod-autoscaler-hpa" aria-label="Permalink to &quot;Horizontal Pod Autoscaler (HPA)&quot;">​</a></h3><p>HPA automatically scales the number of Pod replicas based on CPU utilization, memory usage, or custom metrics. It requires metrics-server and resource requests defined on containers.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Always set resource requests and limits</strong> — Without <code>resources.requests</code>, Kubernetes cannot schedule Pods correctly. Without <code>resources.limits</code>, Pods can consume unbounded resources and starve neighbors.</p></li><li><p><strong>Use namespaces for environment separation</strong> — Create separate namespaces for <code>dev</code>, <code>staging</code>, and <code>production</code>. This provides isolation, quota management, and RBAC boundaries.</p></li><li><p><strong>Implement liveness and readiness probes</strong> — Liveness probes detect and restart stuck containers. Readiness probes control traffic routing. Without them, Kubernetes cannot make intelligent scheduling decisions.</p></li><li><p><strong>Use Deployment with rolling update strategy</strong> — Configure <code>maxSurge</code> and <code>maxUnavailable</code> to control update speed. Use <code>maxUnavailable: 0</code> with <code>maxSurge: 1</code> for zero-downtime deployments.</p></li><li><p><strong>Store configuration in ConfigMaps, not environment variables in manifests</strong> — ConfigMaps are versionable, shareable, and allow configuration changes without rebuilding images.</p></li><li><p><strong>Use Helm charts for templating</strong> — Helm manages complex Kubernetes manifests with templating, versioning, and rollback. Store charts in version control and use <code>values.yaml</code> for environment-specific overrides.</p></li><li><p><strong>Implement network policies</strong> — By default, all Pods can communicate with all other Pods. Use NetworkPolicy resources to restrict traffic between namespaces and services.</p></li><li><p><strong>Monitor with Prometheus and Grafana</strong> — Deploy kube-prometheus-stack for cluster monitoring. Alert on Pod restarts, resource pressure, and deployment failures.</p></li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><p><strong>Running as root in containers</strong> — Use <code>securityContext.runAsNonRoot: true</code> and <code>runAsUser: 1000</code>. Running as root escalates container escape risks.</p></li><li><p><strong>Using <code>latest</code> image tags in deployments</strong> — Always pin to specific versions or SHA digests. <code>latest</code> tags cause unpredictable deployments and broken rollbacks.</p></li><li><p><strong>Storing persistent data in containers</strong> — Containers are ephemeral. Use PersistentVolumes (PV) and PersistentVolumeClaims (PVC) for any data that must survive restarts.</p></li><li><p><strong>Exposing services directly via NodePort in production</strong> — Use Ingress controllers for HTTP routing. NodePort is for development and internal tools only.</p></li><li><p><strong>Not using <code>kubectl diff</code> before apply</strong> — Always review changes before applying. <code>kubectl diff -f manifest.yaml</code> shows what will change.</p></li><li><p><strong>Ignoring Pod disruption budgets</strong> — Without PodDisruptionBudget (PDB), voluntary disruptions (node drains, cluster upgrades) can take down your service. Define PDBs for all production workloads.</p></li><li><p><strong>Hardcoding secrets in manifests</strong> — Never commit secrets to version control. Use external secret managers (Vault, AWS Secrets Manager) or sealed-secrets.</p></li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><p><strong>Forgetting <code>selector</code> in Deployment</strong> — The <code>spec.selector</code> field must match <code>spec.template.metadata.labels</code>. Mismatches cause the Deployment to create infinite ReplicaSets.</p></li><li><p><strong>Using <code>replicas</code> with HPA</strong> — When HPA is configured, remove <code>replicas</code> from the Deployment. HPA manages replica count; manual <code>replicas</code> interfere with autoscaling.</p></li><li><p><strong>Not setting <code>terminationGracePeriodSeconds</code></strong> — Default is 30 seconds. Applications need time to drain connections and flush data. Set it based on your shutdown duration.</p></li><li><p><strong>Assuming Pod IPs are stable</strong> — Pod IPs change on restart. Always use Service DNS names for inter-service communication.</p></li><li><p><strong>Skipping namespace in kubectl commands</strong> — <code>kubectl get pods</code> shows only the current context&#39;s default namespace. Use <code>-n namespace</code> explicitly.</p></li><li><p><strong>Not using <code>imagePullPolicy: IfNotPresent</code> for tagged images</strong> — For version-pinned images, <code>IfNotPresent</code> avoids unnecessary pulls. Only use <code>Always</code> for <code>latest</code> tags.</p></li><li><p><strong>Ignoring resource fragmentation</strong> — Large resource requests cause scheduling failures even when nodes have capacity. Use Vertical Pod Autoscaler (VPA) right-sizing recommendations.</p></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><ul><li><strong>Use Kubernetes when:</strong> You have multiple services, need auto-scaling, require self-healing, or operate across multiple cloud providers.</li><li><strong>Use Docker Compose when:</strong> You&#39;re running a single-node development environment or a simple single-server deployment.</li><li><strong>Use HPA when:</strong> Your workload has predictable traffic patterns (time-of-day, batch processing). Combine with Cluster Autoscaler for node-level scaling.</li><li><strong>Use Helm when:</strong> Your Kubernetes manifests exceed 3 files or you deploy to multiple environments with shared configuration.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Kubernetes Docs: <a href="https://kubernetes.io/docs" target="_blank" rel="noreferrer">https://kubernetes.io/docs</a></li><li>Kubernetes The Hard Way: <a href="https://github.com/kelseyhightower/kubernetes-the-hard-way" target="_blank" rel="noreferrer">https://github.com/kelseyhightower/kubernetes-the-hard-way</a></li><li>Helm Docs: <a href="https://helm.sh/docs" target="_blank" rel="noreferrer">https://helm.sh/docs</a></li><li>k9s (terminal UI): <a href="https://k9scli.io" target="_blank" rel="noreferrer">https://k9scli.io</a></li><li>Lens (desktop UI): <a href="https://k8slens.dev" target="_blank" rel="noreferrer">https://k8slens.dev</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>kubectl get events --sort-by=.lastTimestamp</code> shows recent cluster events for debugging.</li><li><code>kubectl logs pod-name -c container-name --previous</code> shows logs from crashed containers.</li><li><code>kubectl port-forward svc/service-name 8080:80</code> tunnels a remote service to localhost.</li><li><code>kubectl rollout status deployment/name</code> tracks deployment progress.</li><li><code>kubectl rollout undo deployment/name</code> rolls back to the previous revision.</li><li>Use <code>kustomize</code> for simpler templating needs without Helm&#39;s overhead.</li><li>For local Kubernetes, use <code>minikube</code>, <code>kind</code>, or Docker Desktop&#39;s built-in cluster.</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',32)])])}const g=o(a,[["render",n]]);export{h as __pageData,g as default};
